import { isCanonicalTsLabel, sanitizeName, tsLabelToTfLabel } from "../../engine/tf/index.js";
/** Canonical Terraform label for an authored automation task ref key. */
export function taskTfLabel(automationLabel, refKey) {
    // ei's task label is `<auto>_<sanitizeName(task name)>` for display-name
    // stems. Pulled refKeys that are already canonical camelCase (e.g.
    // `commodityBHit_1`) must use the lossless `tsLabelToTfLabel` bijection —
    // `sanitizeName` lowercases before splitCamelCase and collapses
    // single-letter camel segments (`commodityBHit` → `commodityb_hit`), which
    // plans destroy+create against export's `commodity_b_hit_1`.
    //
    // ALLCAPS / SCREAMING_SNAKE refKeys (`GREETING`) also round-trip the
    // bijection (via ugly `_g_r_e_e_t_i_n_g`), but ei's SanitizeName yields
    // `greeting` — require a lowercase letter before preferring the bijection.
    const normalized = isCanonicalTsLabel(refKey) && /[a-z]/.test(refKey)
        ? tsLabelToTfLabel(refKey)
        : sanitizeName(refKey);
    return normalized.startsWith(`${automationLabel}_`) ? normalized : `${automationLabel}_${normalized}`;
}
